"use client";

import * as React from "react";
import { cn } from "./kgcraft-utils";

const DEFAULT_CHARS =
  "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!@#$%^&*";

export interface ScrambleTextProps extends Omit<
  React.HTMLAttributes<HTMLSpanElement>,
  "children"
> {
  text: string;
  speed?: number;
  chars?: string;
  playOnHover?: boolean;
}

export function ScrambleText({
  text,
  speed = 8,
  chars = DEFAULT_CHARS,
  playOnHover = false,
  className,
  onMouseEnter,
  ...props
}: ScrambleTextProps) {
  const [output, setOutput] = React.useState(text);
  const timeoutRef = React.useRef<ReturnType<typeof setTimeout> | null>(null);

  const stop = React.useCallback(() => {
    if (timeoutRef.current) clearTimeout(timeoutRef.current);
    timeoutRef.current = null;
  }, []);

  const play = React.useCallback(() => {
    stop();
    if (
      !chars.length ||
      window.matchMedia("(prefers-reduced-motion: reduce)").matches
    ) {
      setOutput(text);
      return;
    }

    const characters = text.split("");
    let activeIndex = 0;
    let scrambleFrame = 0;

    setOutput(
      characters
        .map((character) => (character === " " ? " " : "\u00a0"))
        .join(""),
    );

    function tick() {
      while (characters[activeIndex] === " ") activeIndex += 1;
      if (activeIndex >= characters.length) {
        setOutput(text);
        stop();
        return;
      }

      setOutput(
        characters
          .map((character, index) => {
            if (character === " " || index < activeIndex) return character;
            if (index === activeIndex)
              return chars[Math.floor(Math.random() * chars.length)];
            return "\u00a0";
          })
          .join(""),
      );

      scrambleFrame += 1;
      if (scrambleFrame >= 3) {
        activeIndex += 1;
        scrambleFrame = 0;
      }
      const frameDelay = Math.max(
        10,
        Math.round(1000 / (Math.max(1, speed) * 3)),
      );
      timeoutRef.current = setTimeout(tick, frameDelay);
    }

    tick();
  }, [chars, speed, stop, text]);

  React.useEffect(() => {
    if (!playOnHover) play();
    return stop;
  }, [play, playOnHover, stop]);

  return (
    <span
      className={cn(
        "relative inline-block font-[Geist,Geist_Sans,ui-sans-serif,system-ui,sans-serif] tracking-tight whitespace-pre",
        className,
      )}
      {...props}
      aria-label={props["aria-label"] ?? text}
      onMouseEnter={(event) => {
        onMouseEnter?.(event);
        if (playOnHover) play();
      }}
    >
      <span className="invisible" aria-hidden="true">
        {text}
      </span>
      <span className="absolute inset-0" aria-hidden="true">
        {output}
      </span>
    </span>
  );
}

import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

/* Generated KGCraft UI theme. Override --kgcraft-* to customize. */
@theme inline {
  --color-kgcraft-background: var(--kgcraft-background);
  --color-kgcraft-primary: var(--kgcraft-primary);
  --color-kgcraft-primary-foreground: var(--kgcraft-primary-foreground);
  --color-kgcraft-secondary: var(--kgcraft-secondary);
  --color-kgcraft-secondary-foreground: var(--kgcraft-secondary-foreground);
  --color-kgcraft-accent: var(--kgcraft-accent);
  --color-kgcraft-accent-foreground: var(--kgcraft-accent-foreground);
  --color-kgcraft-muted-foreground: var(--kgcraft-muted-foreground);
  --color-kgcraft-border: var(--kgcraft-border);
  --color-kgcraft-input: var(--kgcraft-input);
  --color-kgcraft-ring: var(--kgcraft-ring);
}

:root {
  --kgcraft-background: oklch(1 0 0);
  --kgcraft-primary: oklch(0.852 0.199 91.936);
  --kgcraft-primary-foreground: oklch(0.421 0.095 57.708);
  --kgcraft-secondary: oklch(0.967 0.001 286.375);
  --kgcraft-secondary-foreground: oklch(0.21 0.006 285.885);
  --kgcraft-accent: oklch(0.97 0 0);
  --kgcraft-accent-foreground: oklch(0.205 0 0);
  --kgcraft-muted-foreground: oklch(0.556 0 0);
  --kgcraft-border: oklch(0.922 0 0);
  --kgcraft-input: oklch(0.922 0 0);
  --kgcraft-ring: oklch(0.708 0 0);
}

.dark {
  --kgcraft-background: oklch(0.145 0 0);
  --kgcraft-primary: oklch(0.795 0.184 86.047);
  --kgcraft-primary-foreground: oklch(0.421 0.095 57.708);
  --kgcraft-secondary: oklch(0.274 0.006 286.033);
  --kgcraft-secondary-foreground: oklch(0.985 0 0);
  --kgcraft-accent: oklch(0.269 0 0);
  --kgcraft-accent-foreground: oklch(0.985 0 0);
  --kgcraft-muted-foreground: oklch(0.708 0 0);
  --kgcraft-border: oklch(1 0 0 / 10%);
  --kgcraft-input: oklch(1 0 0 / 15%);
  --kgcraft-ring: oklch(0.556 0 0);
}
